const ticket = $json;
const errors = [];

if (!Number.isInteger(ticket.ticket_id) || ticket.ticket_id <= 0) {
  errors.push("ticket_id must be a positive integer");
}

if (typeof ticket.message !== "string" || !ticket.message.trim()) {
  errors.push("message must be a non-empty string");
}

if (typeof ticket.product !== "string" || !ticket.product.trim()) {
  errors.push("product must be a non-empty string");
}

return {
  json: {
    ...ticket,
    is_valid: errors.length === 0,
    error_message: errors.length > 0 ? errors.join("; ") : null
  }
};

const ticket = $json;

let email = typeof ticket.customer_email === "string"
  ? ticket.customer_email.trim().toLowerCase()
  : "";

if (email.endsWith("@gmail.com")) {
  const [username, domain] = email.split("@");
  email = username.split("+")[0] + "@" + domain;
}

return {
  json: {
    ...ticket,
    customer_email: email
  }
};

const ticket = $json;

// Fixed test outputs that imitate an AI classifier.
const mockIntents = {
  10001: "cancellation",
  10002: "cancellation_with_billing_clarification",
  10003: "refund",
  10004: "technical_issue",
  10006: "other"
};

const intent = mockIntents[ticket.ticket_id] ?? null;

return {
  json: {
    ...ticket,
    intent,
    confidence: intent !== null ? 0.95 : 0,
    classification_mode: "mock",
    classification_error: intent !== null
      ? null
      : "No mock classification defined for this ticket"
  }
};

const ticket = $json;

try {
  const subscriptions = Array.isArray(ticket.subscriptions)
    ? ticket.subscriptions
    : [];

  const matchingSubscriptions = subscriptions.filter(
    sub => sub && sub.product === ticket.product
  );

  const activeSubscriptions = matchingSubscriptions.filter(
    sub => sub.status === "active"
  );

  let actionStatus;
  let reason = null;

  if (activeSubscriptions.length === 1) {
    actionStatus = "simulated_success";
  } else if (activeSubscriptions.length === 0) {
    actionStatus = "not_executed";
    reason = "No matching active subscription found";
  } else {
    actionStatus = "requires_review";
    reason = "Multiple matching active subscriptions found";
  }

  const selectedSubscription = activeSubscriptions.length === 1
    ? activeSubscriptions[0]
    : null;

  return {
    json: {
      ...ticket,
      matching_subscription_count: matchingSubscriptions.length,
      active_subscription_count: activeSubscriptions.length,
      action_type: "cancellation",
      action_status: actionStatus,
      details: {
        reason,
        subscription_id: selectedSubscription?.id ?? null,
        billing_provider:
          selectedSubscription?.billing_provider ?? null,
        billing_context: {
          explanation_requested: true,
          charge_reason_verified: false,
          note: "Charge history is unavailable. Do not invent a reason for the charge."
        }
      }
    }
  };

} catch (error) {
  const errorMessage = error instanceof Error
    ? error.message
    : String(error);

  return {
    json: {
      ...ticket,
      matching_subscription_count: null,
      action_type: "cancellation",
      action_status: "not_executed",
      execution_status: "Failed",
      is_error: true,
      error_stage: "cancellation_with_billing_clarification",
      error_message: errorMessage,
      customer_response: null,
      details: {
        reason: errorMessage,
        manual_review_required: true
      }
    }
  };
}

