        : "not_executed",
      details: {
        reason: refundEligible
          ? null
          : "No matching subscription found",
        refund_eligible: refundEligible,
        matching_subscription_ids: matchingSubscriptions.map(
          sub => sub.id
        )
      }
    }
  };

} catch (error) {
