const ticket = $json;

try {
  const subscriptions = Array.isArray(ticket.subscriptions)
    ? ticket.subscriptions
    : [];

  const matchingSubscriptions = subscriptions.filter(
    sub => sub && sub.product === ticket.product
  );

  const knowledgeBase = [
    {
      topic: "freezing",
      response_context:
        "Ask the customer to update the app, restart the device, and retry."
    },
    {
      topic: "login",
      response_context:
        "Ask the customer to verify the account email and reset the password."
    }
  ];

  const text = [
    ticket.subject ?? "",
    ticket.message ?? ""
  ].join(" ").toLowerCase();

  const matchedTopics = [];

  if (/\b(freez\w*|frozen)\b/.test(text)) {
    matchedTopics.push("freezing");
  }

  if (/\b(log\s?in|sign\s?in|password)\b/.test(text)) {
    matchedTopics.push("login");
  }

  const matchedEntry = matchedTopics.length === 1
    ? knowledgeBase.find(
        entry => entry.topic === matchedTopics[0]
      )
    : null;

  return {
    json: {
      ...ticket,
      matching_subscription_count: matchingSubscriptions.length,
      action_type: "technical_support",
      action_status: matchedEntry
        ? "not_executed"
        : "requires_review",
      details: {
        reason: matchedEntry
          ? "Troubleshooting guidance prepared; no system action performed"
          : matchedTopics.length > 1
            ? "Multiple knowledge base topics matched"
            : "No matching knowledge base entry found",
        knowledge_base_topic: matchedEntry?.topic ?? null,
        response_context: matchedEntry?.response_context ?? null,
        manual_review_required: !matchedEntry
      }
    }
  };

} catch (error) {
  const errorMessage = error instanceof Error
    ? error.message
    : String(error);

  return {
    json: {
      ...ticket,
      matching_subscription_count: null,
      action_type: "technical_support",
      action_status: "not_executed",
      execution_status: "Failed",
      is_error: true,
      error_stage: "technical_issue",
      error_message: errorMessage,
      customer_response: null,
      details: {
        reason: errorMessage,
        manual_review_required: true
      }
    }
  };
}

const ticket = $json;

try {
  const subscriptions = Array.isArray(ticket.subscriptions)
    ? ticket.subscriptions
    : [];

  const matchingSubscriptions = subscriptions.filter(
    sub => sub && sub.product === ticket.product
  );

  return {
    json: {
      ...ticket,
      matching_subscription_count: matchingSubscriptions.length,
      action_type: "manual_review",
      action_status: "requires_review",
      details: {
        reason: "Request requires manual review by general support",
        support_queue: "general_support",
        manual_review_required: true,
        response_context:
          "Acknowledge the request and explain that it needs review by the support team. Do not claim that any billing or subscription action was performed."
      }
    }
  };

} catch (error) {
  const errorMessage = error instanceof Error
    ? error.message
    : String(error);

  return {
    json: {
      ...ticket,
      matching_subscription_count: null,
      action_type: "manual_review",
      action_status: "not_executed",
      execution_status: "Failed",
      is_error: true,
      error_stage: "other",
      error_message: errorMessage,
      customer_response: null,
      details: {
        reason: errorMessage,
        manual_review_required: true
      }
    }
  };
}

const ticket = $json;

const validationFailed = ticket.is_valid === false;

const errorStage = validationFailed
  ? "input_validation"
  : "classification";

const errorMessage = validationFailed
  ? ticket.error_message || "Ticket validation failed"
  : ticket.classification_error || "Unknown or missing intent";

return {
  json: {
    ...ticket,
    intent: ticket.intent ?? null,
    matching_subscription_count: null,
    action_type: "none",
    action_status: "not_executed",
    execution_status: "Failed",
    is_error: true,
    error_stage: errorStage,
    error_message: errorMessage,
    customer_response: null,
    details: {
      reason: errorMessage,
      manual_review_required: true
    }
  }
};

const ticket = $json;

return {
  json: {
    ...ticket,
    detected_intent: ticket.intent ?? null,
    matching_subscription_count:
      ticket.matching_subscription_count ?? null,
    action_type: ticket.action_type ?? "none",
    action_status: ticket.action_status ?? "not_executed",
    is_error: ticket.is_error === true,
    error_message: ticket.error_message ?? null,
    details: ticket.details ?? {
      reason: null
    },
    customer_response: ticket.customer_response ?? null
  }
};

const ticket = $json;

// Invalid tickets go to logging without a customer reply.
if (ticket.is_error === true) {
  return {
    json: {
      ...ticket,
      customer_response: null,
      response_mode: "mock",
      response_generation_status: "skipped"
    }
  };
}

let subject = "Your PulseFit request";
let message =
  "Hi, thanks for reaching out. Your request needs review by our support team.";

if (ticket.action_type === "cancellation") {
  subject = "Your cancellation request";

  if (ticket.action_status === "simulated_success") {
    message =
      "Hi, your PulseFit subscription has been cancelled.";

    if (ticket.intent === "cancellation_with_billing_clarification") {
      message +=
        " A support specialist will need to check your payment history to explain the charge.";
    }
  } else if (ticket.action_status === "requires_review") {
    message =
      "Hi, we need to review your subscriptions before completing the cancellation. No subscription has been cancelled yet.";
  } else {
    message =
      "Hi, we couldn't find an active PulseFit subscription to cancel. Please confirm the email used for your subscription.";
  }
}

if (ticket.action_type === "refund") {
  subject = "Your refund request";

  if (ticket.action_status === "simulated_success") {
    message =
      "Hi, your refund has been processed.";
  } else {
    message =
      "Hi, we couldn't process your refund because we couldn't find a matching PulseFit subscription. Please confirm the email used for your subscription.";
  }
}

if (ticket.action_type === "technical_support") {
  subject = "Help with your PulseFit app";

  const topic = ticket.details?.knowledge_base_topic;
  const needsReview = ticket.details?.manual_review_required;

  if (needsReview === false && topic === "freezing") {
    message =
      "Hi, please update the PulseFit app, restart your device, and try again.";
  } else if (needsReview === false && topic === "login") {
    message =
      "Hi, please check that you're using the email associated with your account and reset your password.";
  } else {
    message =
      "Hi, your technical issue needs further review by our support team.";
  }
}

return {
  json: {
    ...ticket,
    customer_response: {
      subject,
      message
    },
    response_mode: "mock",
    response_generation_status: "generated"
  }
};

const ticket = $json;

// Preserve earlier errors and skip response validation.
if (ticket.is_error === true) {
  return {
    json: {
      ...ticket,
      execution_status: "Failed",
      customer_response: null,
      final_validation_status: "skipped"
    }
  };
}

const errors = [];

const allowedIntents = [
  "cancellation",
  "cancellation_with_billing_clarification",
  "refund",
  "technical_issue",
  "other"
];

const allowedStatuses = [
  "simulated_success",
  "not_executed",
  "requires_review",
  "queued"
];

if (!allowedIntents.includes(ticket.detected_intent)) {
  errors.push("Invalid detected intent");
}

if (
  !Number.isInteger(ticket.matching_subscription_count) ||
  ticket.matching_subscription_count < 0
) {
  errors.push("Invalid matching subscription count");
}

if (!allowedStatuses.includes(ticket.action_status)) {
  errors.push("Invalid action status");
}

const response = ticket.customer_response;

if (
  typeof response?.subject !== "string" ||
  !response.subject.trim() ||
  typeof response?.message !== "string" ||
  !response.message.trim()
) {
  errors.push("Customer response must contain a subject and message");
}

// Check that simulated success satisfies the business rule.
if (ticket.action_status === "simulated_success") {
  if (ticket.action_type === "cancellation") {
    if (ticket.active_subscription_count !== 1) {
      errors.push("Cancellation success requires exactly one active subscription");
    }
  } else if (ticket.action_type === "refund") {
    if (!(ticket.matching_subscription_count > 0)) {
      errors.push("Refund success requires a matching subscription");
    }
  } else {
    errors.push("Unexpected action type for simulated success");
  }
}

// Catch success claims used by our mock response templates.
const successClaim =
  /your (pulsefit subscription has been cancelled|refund has been processed)/i;

if (
  successClaim.test(response?.message ?? "") &&
  ticket.action_status !== "simulated_success"
) {
  errors.push("Response claims success without a successful action");
}

const passed = errors.length === 0;

return {
  json: {
    ...ticket,
    execution_status: passed ? "Success" : "Failed",
    is_error: !passed,
    error_stage: passed ? null : "final_validation",
    error_message: passed ? null : errors.join("; "),
    final_validation_status: passed ? "passed" : "failed",
    final_validation_errors: errors,
    customer_response: passed ? response : null
  }
};

const ticket = $json;

return {
  json: {
    timestamp: new Date().toISOString(),
    execution_id: String($execution.id),
    ticket_id: ticket.ticket_id ?? null,
    detected_intent: ticket.detected_intent ?? null,
    matching_subscription_count:
      ticket.matching_subscription_count ?? null,
    action_type: ticket.action_type,
    action_status: ticket.action_status,
    execution_status: ticket.execution_status,
    error_message: ticket.error_message ?? null,
    response_subject: ticket.customer_response?.subject ?? null,
    response_message: ticket.customer_response?.message ?? null,
    final_validation_status: ticket.final_validation_status
  }
};
